        for (int i = 0; i < vertexCount; i++) {
            x = pred[x];
        }

        // Trace the cycle in predecessor order until we revisit x
        List<Integer> traceback = new ArrayList<>();
        int cur = x;
        do {
            traceback.add(cur);
            cur = pred[cur];
        } while (cur != x);

        Collections.reverse(traceback);
        return new NegativeCycle(traceback);
    }
}

